pub type Result<T> = StdResult<T, Error>;

#[derive(Debug, serde::Serialize)]
pub struct Error {
    pub issue: String,
    pub fault: ErrorFault,
    pub solution: &'static str,
}

impl Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let fault_text = match &self.fault {
            ErrorFault::Code(debug) => {
                match debug {
                    Some(debug) => format!("This is due to the code failing.\nDebug details:\n{debug}"),
                    None => "This is due to the code failing.\nThere are no debug details.".to_string(),
                }
            },
            ErrorFault::User => "This is due to a user error.".to_string(),
            ErrorFault::File => "This is due to a file error.".to_string(),
        };

        let issue = &self.issue;
        let solution = &self.solution;

        write!(f, "{issue}\n{fault_text}\n{solution}")
    }
}

#[derive(Debug, serde::Serialize)]
pub enum ErrorFault {
    Code(Option<String>),
    User,
    File,
}

fn assert(assertion: bool, issue: &'static str, solution: &'static str, fault: ErrorFault) -> Result<()> {
    if assertion {
        Result::Ok(())
    } else {
        Result::Err(Error { issue: issue.to_string(), fault, solution })
    }
}

fn assert_internal<const ERROR_NUM: u8>(assertion: bool, debug: Option<String>) -> Result<()> {
    if assertion {
        Result::Ok(())
    } else {
        Result::Err(Error {
            issue: format!("Internal Error #{ERROR_NUM:0>3}"),
            fault: ErrorFault::Code(debug),
            solution: "Try again, or try moving the seed point slightly.",
        })
    }
}

