pub enum Connectivity {
    OnVertex(usize),
    /// Not to be used manually, as it leads to duplicates if the usizes are swapped.
    OnEdge(usize, usize)
}

impl Connectivity {
    fn on_edge(a: usize, b: usize) -> Self {
        let (a, b) = if a >= b {
            (a, b)
        } else {
            (b, a)
        };
        Self::OnEdge(a, b)
    }
}

